/-- For [the r input](hyp:r), [the k input](hyp:k), [this defines the get object](goal). -/
def InsulinCDFCutoffRow.get (r : InsulinCDFCutoffRow) (k : Fin 4) : RatInterval :=
  r.data[k.val]'(by rw [r.size_eq]; exact k.isLt)

/-- For [the r input](hyp:r), [the s input](hyp:s), [this defines the get object](goal). -/
def InsulinCDFTable.get (r : InsulinCDFTable) (s : Fin 360) : InsulinCDFActionRow :=
  r.data[s.val]'(by rw [r.size_eq]; exact s.isLt)

/-- Stationarity of a finite probability vector for a transition matrix. -/
def IsStationary {S : Type*} [Fintype S] (P : S → S → ℝ) (d : S → ℝ) : Prop :=
  ProbabilityVector d ∧ ∀ s', ∑ s, d s * P s s' = d s'

/-- Measurable observable-data estimators taking values in `[-1,1]`. -/
def ObservableEstimator (T : Nat) : Type :=
  {est : RawEstimator T //
    (∀ nX b e w, est nX b e w ∈ Set.Icc (-1 : ℝ) 1) ∧
    (∀ nX b e, Measurable (est nX b e))}

/-- The target policy is a probability policy dominated by `L` times the behavior policy. -/
def PolicyOverlap {T nX nH : Nat} (L : ℝ) (M : RawPomdpExperiment T nX nH) : Prop :=
  PolicyVector M.e ∧ ∀ x a, M.e x a ≤ L * M.b x a

/-- A policy is pointwise a probability vector on the binary action set. -/
def PolicyVector {nX : Nat} (p : Policy nX) : Prop :=
  ∀ x, (∀ a, 0 ≤ p x a) ∧ ∑ a : Bool, p x a = 1

/-- A finite vector is a probability vector. -/
def ProbabilityVector {S : Type*} [Fintype S] (p : S → ℝ) : Prop :=
  (∀ i, 0 ≤ p i) ∧ ∑ i, p i = 1

/-- Read the observed current state from the state-history view. -/
def currentObsState {T nX nH : Nat} (t : Fin T) (h :
    StateHistoryView T nX nH t) : Fin nX := h.2.1

/-- Add a natural offset to an epoch while retaining the explicit horizon proof. -/
def epochAdd {T : Nat} (r : Fin T) (m : Nat) (hm : r.val + m < T) : Fin T :=
  ⟨r.val + m, hm⟩

/-- The state history with the current action adjoined. -/
def histActionPair {T nX nH : Nat} (t : Fin T) (tau : FullTrajectory T nX nH) :=
  (histStateView t tau, actionAt t tau)

/-- The kernel conditioning view with `(Y_t,S_{t+1})` adjoined. -/
def histNextPair {T nX nH : Nat} (t : Fin T) (tau : FullTrajectory T nX nH) :=
  (histView t tau, (rewardAt t tau, nextState t tau))

/-- For [the i input](hyp:i), [this defines the insulin Activity Rat object](goal). -/
def insulinActivityRat (i : ℕ) : ℚ :=
  if i = 0 then 0 else if i = 1 then 31 else 850

/-- For [the s input](hyp:s), [the a input](hyp:a), [the k input](hyp:k), [this defines the insulin CDFArgument object](goal). -/
def insulinCDFArgument (s : JointState 90 4) (a : Bool) (k : Fin 4) : ℚ :=
  (insulinCutoff k - insulinMeanRat s a) / 5

/-- For [the s input](hyp:s), [the a input](hyp:a), [the k input](hyp:k), [this defines the insulin CDFEntry object](goal). -/
def insulinCDFEntry (s : JointState 90 4) (a : Bool) (k : Fin 4) : RatInterval :=
  insulinCDFEntryWithTable insulinCDFTable s a k

/-- For [the q input](hyp:q), [this defines the insulin CDFInterval object](goal). -/
def insulinCDFInterval (q : ℚ) : RatInterval :=
  quantizeInterval (10 ^ 12) (by positivity) (insulinCDFRawInterval q)

/-- For [the target input](hyp:target), [this defines the insulin Certified Initial object](goal). -/
def insulinCertifiedInitial (target : Bool) : RationalProbabilityVector (Fin 360) :=
  if target then insulinTrueCertifiedInitial else insulinFalseCertifiedInitial

/-- For [the c input](hyp:c), [this defines the insulin Chunk Indices object](goal). -/
def insulinChunkIndices (c : Fin 9) : Finset (JointState 90 4) :=
  Finset.univ.map (insulinChunkEmbedding c)

/-- For [the target input](hyp:target), [this defines the insulin Chunked Stationary Reward Interval object](goal). -/
def insulinChunkedStationaryRewardInterval (target : Bool) : RatInterval :=
  let radius := insulinGeneratedResidual target / (1 - 1 / 2)
  (intervalExpectation (insulinGeneratedTrace target 0) insulinRewardIntervals).expand
    radius (div_nonneg (insulinGeneratedResidual_nonneg target) (by norm_num))

/-- For [the lo input](hyp:lo), [the hi input](hyp:hi), [this defines the insulin Interval From Endpoints object](goal). -/
def insulinIntervalFromEndpoints (lo hi : ℚ) : RatInterval :=
  ⟨min lo hi, max lo hi, min_le_max⟩

/-- [this defines the insulin Normalization Certificate object](goal). [defining clause 1](step:1); and [defining clause 2](step:2). -/
def insulinNormalizationCertificate : NormalizationCertificate where
  schedule := { fuel := 10 }
  enclosure := normalizationInterval { fuel := 10 }

/-- [this defines the insulin Reward Intervals object](goal). -/
def insulinRewardIntervals : IntervalVector (JointState 90 4) :=
  fun s => RatInterval.point (insulinRewardRat (insulinRewardSymbolRat s.1))

