/-- The successor epoch associated with a nonterminal epoch. -/
def nextEpoch {T : Nat} (t : Fin T) (ht : t.val + 1 < T) : Fin T :=
  ⟨t.val + 1, ht⟩

/-- Projection from the full trajectory to exactly the information observed by an estimator. -/
def obsProj {T nX nH : Nat} (tau : FullTrajectory T nX nH) : ObsView T nX :=
  fun t ↦ ((curState t tau).1, actionAt t tau, rewardAt t tau)

/-- For [the k input](hyp:k), [the t input](hyp:t), [this defines the phiw Window object](goal). -/
def phiwWindow {T : Nat} (k : Nat) (t : Fin T) : Finset (Fin T) :=
  Finset.univ.filter (fun j : Fin T ↦ j.val ≤ t.val ∧ t.val - j.val ≤ k)

/-- Embed a prefix coordinate into a horizon with `U` additional epochs. -/
def prefixExtraIndex (U : Nat) {k : Nat} (j : Fin k) : Fin (U + k) :=
  ⟨j.val, lt_of_lt_of_le j.isLt (Nat.le_add_left k U)⟩

/-- The probability simplex inside the finite `L¹` vector space. -/
def probabilityL1Set (S : Type*) [Fintype S] : Set (L1Vec S) :=
  {x | ProbabilityVector (WithLp.ofLp x)}

/-- Remove the deterministic observed-state coordinate from a singleton-state observed word. -/
def signedDepthObservedActions {k : Nat} (w : FiniteObsView k 1 2) : ObsPrefix k :=
  fun i ↦ ((w i).2.1, (w i).2.2)

/-- The joint state at a path coordinate, including the terminal coordinate. -/
def stateAt {T nX nH : Nat} (i : Fin (T + 1))
    (tau : FullTrajectory T nX nH) : JointState nX nH := tau.1 i
